              </DialogTrigger>
              <DialogContent className="max-h-[85vh] max-w-3xl overflow-y-auto">
                <DialogHeader>
                  <DialogTitle>Operating balance</DialogTitle>
                </DialogHeader>
                <WalletPanel />
              </DialogContent>
            </Dialog>
