                        <span className={item.credit ? "font-semibold text-emerald-500" : "font-semibold"}>
                          {item.credit ? "+" : "−"}
                          {money(item.amountCents)}
                        </span>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
