/**
 * Ports of production Moov Edge Functions.
 * Source: supabase/functions/moov-* /index.ts and _shared/moovClient.ts
 * Staging binds sandbox credentials only and writes environment='sandbox' rows.
 */
import { evaluateReadiness } from '../readiness.mjs';
import {
  MoovError,
  capabilityFlags,
  facilitatorAccountId,
  lastMoovRequestHeaders,
  moovFetch,
  moovToken,
  normalizeOnboardingStatus,
  normalizeTransferStatus,
  scopes,
  withMoovContext,
} from './moov-client.mjs';
import { fail, jsonResult, moovParityContext, isChecksOpsPlatformOwner } from './caller.mjs';
import {
  MERCHANT_CAPABILITIES,
  MOOV_CAPABILITIES_API_VERSION,
  missingRequestedCapabilities,
} from './moov-capabilities.mjs';
import { loadMoovAccount, logPaymentEvent, sanitize } from './db.mjs';
import { applyMoovBanksToStakeholders, syncLinkedStakeholderBanks } from './moov-stakeholder-sync.mjs';
import { readWallet, syncWallet } from './moov-wallet.mjs';
import {
  cancelWalletFunding,
  calculatePaymentFunding,
  disburse,
  initiateWalletFunding,
  processFundedPayment,
  tenantFeeCharge,
  transferCreate,
  transferGroupCreate,
  walletFund,
  walletFundOnClear,
} from './moov-money.mjs';
import {
  accountFileUpload,
  accountFileView,
  accountFiles,
  accountOnboard,
  bankAccountAdd,
  bankLinkToken,
  bulkImportPreview,
  feeRollup,
  feeScheduleCancel,
  feeScheduleUpsert,
  homeownerDeductiblePay,
  invoice,
  microDepositConfirm,
  microDepositInitiate,
  onboardingLink,
  plaidBridge,
  platformBank,
  platformTreasury,
  publicInvoice,
  recipientBankAdd,
  recipientBankVerify,
