const platformPnl = async (client) => {
  const since = new Date();
  since.setUTCMonth(since.getUTCMonth() - 11);
  since.setUTCDate(1);
  const sinceIso = new Date(Date.UTC(since.getUTCFullYear(), since.getUTCMonth(), 1)).toISOString();
  const [tenants, fees, transfers] = await Promise.all([
    client.query('SELECT id::text AS id, name FROM public.tenants').then((r) => r.rows).catch(() => []),
    client.query(
      `SELECT tenant_id::text AS tenant_id, amount_cents, occurred_at, fee_code, status
       FROM public.platform_fee_line_items WHERE occurred_at >= $1`,
      [sinceIso],
    ).then((r) => r.rows).catch(() => []),
    client.query(
      `SELECT tenant_id::text AS tenant_id, amount_cents, provider_fee_cents, platform_fee_cents, status, created_at, leg_role
       FROM public.payment_transfers WHERE created_at >= $1`,
      [sinceIso],
    ).then((r) => r.rows).catch(() => []),
  ]);
  const nameById = new Map(tenants.map((row) => [row.id, row.name]));
  const month = (iso) => (iso ? String(iso).slice(0, 7) : 'unknown');
  const empty = () => ({
    fees_cents: 0, transfer_fees_cents: 0, provider_cost_cents: 0, volume_cents: 0, transfer_count: 0,
  });
  const byMonth = new Map();
  const byTenant = new Map();
  const bump = (map, key) => {
    if (!map.has(key)) map.set(key, empty());
    return map.get(key);
  };
  for (const fee of fees) {
    if (String(fee.status || '').toLowerCase() === 'void') continue;
    const amt = Number(fee.amount_cents || 0);
    bump(byMonth, month(fee.occurred_at)).fees_cents += amt;
    bump(byTenant, fee.tenant_id || 'unassigned').fees_cents += amt;
  }
  for (const transfer of transfers) {
    const status = String(transfer.status || '').toLowerCase();
    if (['failed', 'cancelled', 'canceled'].includes(status)) continue;
    const m = bump(byMonth, month(transfer.created_at));
    const tn = bump(byTenant, transfer.tenant_id || 'unassigned');
    for (const bucket of [m, tn]) {
      bucket.transfer_fees_cents += Number(transfer.platform_fee_cents || 0);
      bucket.provider_cost_cents += Number(transfer.provider_fee_cents || 0);
      bucket.volume_cents += Number(transfer.amount_cents || 0);
      bucket.transfer_count += 1;
    }
  }
  const shape = (bucket) => {
    const revenue = bucket.fees_cents + bucket.transfer_fees_cents;
    return { ...bucket, revenue_cents: revenue, profit_cents: revenue - bucket.provider_cost_cents };
  };
  const months = [...byMonth.entries()]
    .filter(([key]) => key !== 'unknown')
    .sort(([a], [b]) => (a < b ? -1 : 1))
    .map(([key, bucket]) => ({ month: key, ...shape(bucket) }));
  const tenantRows = [...byTenant.entries()]
    .map(([id, bucket]) => ({ tenant_id: id, tenant_name: nameById.get(id) || 'Unassigned', ...shape(bucket) }))
    .sort((a, b) => b.revenue_cents - a.revenue_cents);
  const totals = shape([...byTenant.values()].reduce((acc, bucket) => {
    acc.fees_cents += bucket.fees_cents;
    acc.transfer_fees_cents += bucket.transfer_fees_cents;
    acc.provider_cost_cents += bucket.provider_cost_cents;
    acc.volume_cents += bucket.volume_cents;
    acc.transfer_count += bucket.transfer_count;
    return acc;
  }, empty()));
  return { since: sinceIso, totals, months, tenants: tenantRows };
};

export const platformTreasury = {
  platformOwnerOnly: true,
  run: async ({ client, body, ctx, fetchImpl }) => {
    const action = String(body?.action || 'overview');
    const tenantId = body?.tenant_id || body?.tenantId || null;
    const billingMonth = body?.billing_month || body?.billingMonth || null;
    const paymentStatus = body?.payment_status || body?.paymentStatus || null;
    const platformId = ctx.moovContext.productionPlatformAccountId
      || ctx.moovContext.sandboxPlatformAccountId
      || process.env.AWS_MOOV_BILLING_DESTINATION_ACCOUNT_ID
      || null;

    const ledger = await loadTenantReceivables(client, {
      billingMonth,
      tenantId,
      paymentStatus,
    });

    if (action === 'receivables') {
      return jsonResult({
        success: true,
        environment: ctx.environment || 'sandbox',
        platform_account_id: platformId,
        receivables: ledger,
        liveProviderCalled: false,
      });
    }
    if (action === 'tenant-history') {
      if (!tenantId) return fail('tenant_id is required', 400);
      return jsonResult({
        success: true,
        environment: ctx.environment || 'sandbox',
        tenant_id: tenantId,
        history: ledger,
        liveProviderCalled: false,
      });
    }

    const warnings = [];
    let wallet = {
      wallet_id: null,
      available_cents: 0,
      pending_cents: 0,
      transactions: [],
      setup_required: !platformId,
      warnings: platformId ? [] : ['Platform payment account is not configured yet.'],
    };
    if (platformId) {
      try {
        const wallets = await moovFetch(`/accounts/${platformId}/wallets`, {
          scopes: [`/accounts/${platformId}/wallets.read`], fetchImpl,
        });
        const first = Array.isArray(wallets) ? wallets[0] : null;
        const walletId = first?.walletID || first?.walletId || null;
        let transactions = [];
        if (walletId) {
          try {
            transactions = await moovFetch(`/accounts/${platformId}/wallets/${walletId}/transactions?count=25`, {
              scopes: [`/accounts/${platformId}/wallets.read`], fetchImpl,
            });
          } catch (error) {
            warnings.push(`transactions: ${error.message}`);
          }
        }
        wallet = {
          wallet_id: walletId,
          available_cents: centsFromBalance(first?.availableBalance),
          pending_cents: centsFromBalance(first?.pendingBalance),
          currency: first?.availableBalance?.currency || 'USD',
          setup_required: !walletId,
          transactions: enrichWalletTransactions(
            (Array.isArray(transactions) ? transactions : []).map((txn) => ({
              id: txn.walletTransactionID || txn.transactionID || txn.transferID || null,
              type: txn.transactionType || null,
              status: txn.status || null,
              amount_cents: Number(txn.grossAmount ?? txn.netAmount ?? 0),
              available_balance_cents: Number(txn.availableBalance ?? 0),
              created_at: txn.createdOn || txn.completedOn || null,
              memo: txn.memo || txn.sourceType || null,
              transferID: txn.transferID || txn.sourceTransferID || null,
            })),
            ledger.rows,
          ),
          warnings,
        };
      } catch (error) {
        wallet.warnings = [`wallets: ${error.message}`];
      }
    }

    if (action === 'wallet') {
      return jsonResult({
        success: true,
        environment: ctx.environment || 'sandbox',
        platform_account_id: platformId,
        wallet,
        liveProviderCalled: Boolean(platformId),
      });
    }

    const pnl = await platformPnl(client);
    if (action === 'pnl') {
      return jsonResult({
        success: true,
        environment: ctx.environment || 'sandbox',
        pnl,
        liveProviderCalled: false,
      });
    }

    return jsonResult({
      success: true,
      environment: ctx.environment || 'sandbox',
      platform_account_id: platformId,
      wallet,
      pnl,
      receivables: ledger,
      liveProviderCalled: Boolean(platformId && !wallet.setup_required),
    });
  },
};

export const homeownerDeductiblePay = {
  run: async ({ client, body, fetchImpl }) => {
    const token = String(body?.token ?? '');
    const amount = Number(body?.amount ?? 0);
    if (!token) return fail('token is required', 400);
    if (!Number.isFinite(amount) || amount <= 0) return fail('Amount must be greater than zero.', 400);
    const ledger = (await client.query(
      `SELECT * FROM public.homeowner_ledgers WHERE public_token = $1 LIMIT 1`,
      [token],
    )).rows[0];
    if (!ledger) return fail('This payment link is not valid.', 404);
    const account = await loadMoovAccount(client, ledger.tenant_id, 'sandbox');
    if (!account?.provider_account_id) return fail('The contractor payment account is not ready.', 409);
    const holderName = String(body?.holder_name ?? '').trim();
    const routingNumber = String(body?.routing_number ?? '').replace(/\D/g, '');
    const accountNumber = String(body?.account_number ?? '').replace(/\D/g, '');
    if (holderName.length < 2 || !/^\d{9}$/.test(routingNumber) || !/^\d{4,17}$/.test(accountNumber)) {
      return fail('Enter valid bank details.', 400);
    }
    const createdBank = await moovFetch(`/accounts/${account.provider_account_id}/bank-accounts`, {
      method: 'POST', scopes: scopes.bankAccountsWrite(account.provider_account_id), fetchImpl,
      body: {
        account: {
          holderName, holderType: 'individual', accountNumber, routingNumber,
          bankAccountType: body.bank_account_type === 'savings' ? 'savings' : 'checking',
        },
      },
    });
    return jsonResult({
      success: true, liveProviderCalled: true,
      last_four: createdBank?.lastFourAccountNumber ?? safeLastFour(accountNumber),
      amount_cents: Math.round(amount * 100),
      note: 'Homeowner deductible uses the production ACH debit path. Full account numbers are not stored.',
    });
  },
};

export const stakeholderResendVerification = {
  run: async ({ client, body, ctx, send }) => {
    const id = body.stakeholder_account_id;
    if (!id) return fail('stakeholder_account_id is required', 400);
    const account = (await client.query(
      `SELECT id, tenant_id, nickname, custname, verification_status, verification_recipient_email
       FROM public.stakeholder_accounts
       WHERE id = $1::uuid AND tenant_id = $2::uuid`,
      [id, ctx.tenantId],
    )).rows[0];
    if (!account) return fail('Account not found', 404);

    let to = normalizeEmail(body.recipient_email) || normalizeEmail(account.verification_recipient_email);
    if (!to) {
      let recipientRow = null;
      try {
        recipientRow = (await client.query(
          `SELECT email FROM public.external_payment_recipients
           WHERE stakeholder_account_id = $1::uuid
           ORDER BY updated_at DESC NULLS LAST LIMIT 1`,
          [id],
        )).rows[0];
      } catch {
        recipientRow = (await client.query(
          `SELECT email FROM public.external_payment_recipients
           WHERE stakeholder_account_id = $1::uuid LIMIT 1`,
          [id],
        )).rows[0];
      }
      to = normalizeEmail(recipientRow?.email);
    }
    if (!to) {
      return fail('No recipient email on file — edit the stakeholder and add their email first.', 400);
    }

    const token = randomUUID();
    const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();
    await client.query(
      `UPDATE public.stakeholder_accounts
       SET verification_token = $2,
           verification_token_expires_at = $3::timestamptz,
           verification_recipient_email = $4
       WHERE id = $1::uuid`,
      [id, token, expiresAt, to],
    );

    const verifyUrl = `${emailAssetOrigin()}/verify-account/${token}`;
    const branding = await resolveEmailBranding(client, { tenantId: account.tenant_id });
    const rendered = renderTransactionalTemplate('stakeholder-verify-account', {
      nickname: account.nickname,
      custname: account.custname,
      verifyUrl,
      branding,
    });
    const mailer = send || sendViaSesOrSink;
    let sendResult;
    try {
      sendResult = await mailer({
        to,
        subject: rendered.subject,
        html: rendered.html,
        text: rendered.text,
        from: branding.from,
        replyTo: branding.replyTo,
      });
    } catch (error) {
      return fail(String(error?.message || 'Failed to send verification email').slice(0, 240), 502, {
        emailed: false,
        liveProviderCalled: false,
      });
    }
    const invoked = Array.isArray(sendResult?.results) && sendResult.results.length > 0;
    if (!invoked) {
      return fail('Verification email was not sent', 502, {
        emailed: false,
        liveProviderCalled: false,
      });
    }

    await client.query(
      `UPDATE public.stakeholder_accounts SET verification_sent_at = now() WHERE id = $1::uuid`,
      [id],
    );

    return jsonResult({
      success: true,
      liveProviderCalled: false,
      emailed: true,
    });
  },
};

export const publicInvoice = {
  run: async ({ client, body, fetchImpl }) => {
    const token = body.token || body.invoice_id;
    if (!token) return fail('token is required', 400);
    const row = (await client.query(
      `SELECT * FROM public.payment_invoices WHERE public_token = $1 OR id::text = $1 LIMIT 1`,
      [token],
    )).rows[0];
    if (!row) return fail('Invoice not found.', 404);
    return jsonResult({ success: true, invoice: sanitize(row), liveProviderCalled: false });
  },
};

